package com.gitgalaxy.modernized.batch;

import com.gitgalaxy.modernized.service.CbexportService;
import java.util.List;
import org.springframework.batch.core.Job;
import org.springframework.batch.core.job.builder.JobBuilder;
import org.springframework.batch.core.repository.JobRepository;
import org.springframework.batch.core.step.builder.StepBuilder;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.transaction.PlatformTransactionManager;

/** JCL job CBEXPORT (app/jcl/CBEXPORT.jcl) as a Spring Batch job (#3622): its steps in JCL order,
 *  each bypassed when its COND= (or the job's) is satisfied, as JCL does.
 *  JCL job flow field testing: open (5 public / 0 private estates). */
@Configuration
public class CbexportJobConfig {

    static final List<Dd> DDS_STEP01 = List.of();
    static final List<Dd> DDS_STEP02 = List.of(new Dd("STEPLIB", "AWS.M2.CARDDEMO.LOADLIB", "SHR", null, null), new Dd("CUSTFILE", "AWS.M2.CARDDEMO.CUSTDATA.VSAM.KSDS", "SHR", null, null), new Dd("ACCTFILE", "AWS.M2.CARDDEMO.ACCTDATA.VSAM.KSDS", "SHR", null, null), new Dd("XREFFILE", "AWS.M2.CARDDEMO.CARDXREF.VSAM.KSDS", "SHR", null, null), new Dd("TRANSACT", "AWS.M2.CARDDEMO.TRANSACT.VSAM.KSDS", "SHR", null, null), new Dd("CARDFILE", "AWS.M2.CARDDEMO.CARDDATA.VSAM.KSDS", "SHR", null, null), new Dd("EXPFILE", "AWS.M2.CARDDEMO.EXPORT.DATA", "SHR", null, null));

    @Bean
    public Job cbexportJob(JobRepository jobRepository, PlatformTransactionManager tx, JclSteps steps, CbexportService cbexportService) {
        return new JobBuilder("CBEXPORT", jobRepository)
                .start(new StepBuilder("STEP01", jobRepository)
                        .tasklet(steps.utility("STEP01", "STEP01", null, null, null, "IDCAMS", "STEP01 runs the utility IDCAMS (its control statements are in SYSIN) -- a utility step to port"), tx).build())
                .next(new StepBuilder("STEP02", jobRepository)
                        .tasklet(steps.program("STEP02", "STEP02", null, null, null, () -> cbexportService.runBatch(DDS_STEP02, null)), tx).build())
                .build();
    }
}
